<script lang="ts">
 import type {FormalWorkPackage,RuntimeRecord,WriterLockState} from '../lib/model/entityTypes.ts';
 import type {RunLayer2Record} from '../lib/runtimeResultFeedbackControlLoopProjection.ts';
 import {buildRuntimeObserver,ownerAcceptanceLabel,runtimeHealthLabel,runtimeStatusLabel,writerLockLabel} from '../lib/runtimeObserver.ts';
 import {formatOwnerLocalTime} from '../lib/ownerTime.ts';
 export let runtime:RuntimeRecord|null=null; export let runLayer2:RunLayer2Record|null=null; export let workPackage:FormalWorkPackage|null=null; export let writerLock:WriterLockState={status:'UNAVAILABLE',scope:'repository'}; export let emptyTitle='暂无运行记录'; export let emptyCapability='不可用'; export let emptyReason=''; export let resultText:string|null=null; export let resultExpanded=false; export let copied=false; export let onToggleResult:(expanded:boolean)=>void=()=>{}; export let onCopyResult:()=>void=()=>{};
 $: projectedLifecycle=runLayer2?.lifecycle.state==='KNOWN'?runLayer2.lifecycle.value:null;
 $: model=buildRuntimeObserver(runtime&&typeof runtime==='object'?runtime:null,workPackage,writerLock,Date.now(),projectedLifecycle);
 $: elapsed=model.elapsedMs===null?'不可用':`${Math.floor(model.elapsedMs/60000)}m ${Math.floor(model.elapsedMs/1000)%60}s`;
</script>
<section class="runtime-monitor runtime-summary-pane" data-testid="runtime-monitor" data-runtime-status={model.status}>
 <div>
 <div class="runtime-summary"><div><span class="runtime-kicker">{runtimeStatusLabel(model.status)} <small>{model.status}</small></span><h3>{runtime?model.summary:emptyTitle}</h3>{#if runtime}<dl class="aicc-info-list runtime-summary-info"><div class="aicc-info-row"><dt class="aicc-info-label">当前活动</dt><dd class="aicc-info-value" title={model.activity}>{model.activity}</dd></div><div class="aicc-info-row"><dt class="aicc-info-label">最近活动</dt><dd class="aicc-info-value">{formatOwnerLocalTime(runtime.lastActivityAt)}</dd></div><div class="aicc-info-row"><dt class="aicc-info-label">耗时</dt><dd class="aicc-info-value">{elapsed}</dd></div></dl>{:else}<p>执行能力：{emptyCapability}</p>{#if emptyReason}<p>原因：{emptyReason}</p>{/if}{/if}</div></div>
 <dl class="aicc-info-list runtime-health"> <div class="aicc-info-row"><dt class="aicc-info-label">运行健康</dt><dd class={`aicc-info-value ${model.health.toLowerCase()}`}>{runtimeHealthLabel(model.health)} · {model.health}</dd></div><div class="aicc-info-row"><dt class="aicc-info-label">写入锁</dt><dd class="aicc-info-value">{writerLockLabel(model.writerLock.status)} · {model.writerLock.status}</dd></div><div class="aicc-info-row"><dt class="aicc-info-label">实施验收</dt><dd class="aicc-info-value">{model.acceptance.progress===null?'不可用':`${model.acceptance.progress}%`}</dd></div><div class="aicc-info-row"><dt class="aicc-info-label">进程</dt><dd class="aicc-info-value">{model.process==='ALIVE'?'运行中':model.process==='DEAD'?'已结束':'不可用'} · {model.process}</dd></div></dl>
 <dl class="aicc-info-list runtime-metrics">{#each [['Agent 消息',model.metrics.agentMessages],['命令',model.metrics.commands],['变更事件',model.metrics.fileChanges],['工具调用',model.metrics.toolCalls],['错误',model.metrics.errors] ] as metric}<div class="aicc-info-row"><dt class="aicc-info-label">{metric[0]}</dt><dd class="aicc-info-value">{metric[1]===null?'不可用':metric[1]}</dd></div>{/each}</dl>
 {#if model.events.length}<div class="runtime-events"><b>实时活动</b>{#each model.events as event}<div><span>{formatOwnerLocalTime(event.timestamp)}　{event.label}</span><code>{event.technicalType}</code></div>{/each}</div>{/if}
 {#if model.acceptance.items.length}<div class="runtime-acceptance"><b>验收清单</b><small>实施验收不代表 Work Package 已完成。</small>{#each model.acceptance.items as item}<div><span class={item.state.toLowerCase()}>{item.state==='PASS'?'✓ 已通过':item.state==='PENDING'?'● 待验证':'○ 尚无证据'}</span><span>{ownerAcceptanceLabel(item.label)}</span></div>{/each}</div>{/if}
 {#if runtime}<details class="runtime-technical"><summary>技术详情</summary><div>Run ID: {runtime.runId}</div><div>Execution Type: {runtime.executionType??'不可用'} · Sandbox: {runtime.sandboxMode??'不可用'}</div><div>HEAD: {runtime.authorizedHead??runtime.startingHeadSha??'不可用'} · PID: {runtime.pid??'不可用'} · Thread: {runtime.threadId??'不可用'}</div><div>Start: {formatOwnerLocalTime(runtime.startedAt)} · End: {formatOwnerLocalTime(runtime.completedAt)}</div><div>exit code: {runtime.exitCode??'不可用'}</div><div>Implementation: {runtime.implementationResult??'不可用'}</div>{#if runtime.stderr}<div>stderr: <code>{runtime.stderr}</code></div>{/if}</details><details class="runtime-result-panel" data-testid="runtime-result-panel" open={resultExpanded} ontoggle={(event)=>onToggleResult((event.currentTarget as HTMLDetailsElement).open)}><summary><span>运行结果</span><button class="runtime-result-copy" type="button" disabled={!resultText} aria-label={copied?'已复制运行结果':'复制运行结果'} title={copied?'已复制':'复制运行结果'} onclick={(event)=>{event.preventDefault();event.stopPropagation();onCopyResult()}}>{#if copied}✓{:else}<svg viewBox="0 0 16 16" aria-hidden="true"><rect x="5" y="5" width="8" height="8" rx="1"/><path d="M3 11V3h8"/></svg>{/if}</button></summary>{#if resultText}<pre data-testid="runtime-result-content">{resultText}</pre>{:else if ['COMPLETED','FAILED','STOPPED'].includes(runtime.phase)}<p class="runtime-result-empty" data-testid="runtime-result-empty">等待 Codex 结果…</p>{:else}<p class="runtime-result-empty">等待 Codex 结果…</p>{/if}</details>{/if}
 </div>
</section>
